<script setup lang="ts">
import {t as tr} from "../i18n";
import {onMounted,ref} from 'vue';import {businessApi,useBusinessStore} from '../stores/business';import {useVisibleRefresh} from '../composables/useVisibleRefresh';import type {HomeSummary} from '@shared/mobile';import type {Target} from '@shared/labops-targets.js';import AsyncState from './AsyncState.vue';import UiIcon from '../components/UiIcon.vue';
const emit=defineEmits<{navigate:[Target]}>(),business=useBusinessStore(),data=ref<HomeSummary>(),loading=ref(true),error=ref(''),expanded=ref<Record<string,boolean>>({}),tasksSection=ref<HTMLElement>(),plansSection=ref<HTMLElement>(),shiftsSection=ref<HTMLElement>();let generation=0;
const kinds:Record<string,string>={'issue.create':'报修','issue.action':'工单','duty.handover':'检查交接','duty.accept':'接收交接','schedule.move':'调课','closure.create':'停用','closure.revoke':'恢复开放','incident.bundle':'故障处置'};
const states:Record<string,string>={awaiting_confirmation:'待确认',draft:'草稿',stale:'需重算',expired:'已过期',executed:'已提交',in_progress:'处理中',open:'待处理',processing:'处理中',resolved:'已完成'};
async function refresh(){const epoch=++generation,scope=business.scopeKey;try{const result=await businessApi<HomeSummary>('proxy/mobile-home');if(scope===business.scopeKey&&epoch===generation){data.value=result;error.value='';}}catch(e){if(epoch===generation)error.value=(e as Error).message;}finally{if(epoch===generation)loading.value=false;}}
onMounted(refresh);useVisibleRefresh(refresh);
</script>
<template><AsyncState :loading="loading" :error="error" @retry="refresh"><template v-if="data">
<div class="mobile-greeting mobile-home-title"><h2>{{data.actor.name}}{{tr("的工作台")}}</h2><span>{{data.date}}</span></div>
<div class="mobile-counts"><button @click="tasksSection?.scrollIntoView({block:'start'})"><b>{{data.counts.tasks}}</b>{{tr("本人待办")}}</button><button @click="plansSection?.scrollIntoView({block:'start'})"><b>{{data.counts.pendingPlans}}</b>{{tr("待确认")}}</button><button @click="emit('navigate',{view:'messages'})"><b>{{data.counts.unread}}</b>{{tr("未读消息")}}</button><button @click="shiftsSection?.scrollIntoView({block:'start'})"><b>{{data.counts.shifts}}</b>{{tr("今日班次")}}</button></div>
<nav class="mobile-quick-grid" :aria-label="tr('工作快捷入口')"><button @click="emit('navigate',{view:'assistant',section:'work'})"><UiIcon name="new"/>{{tr("新建工作会话")}}</button><button @click="emit('navigate',{view:'rooms'})"><UiIcon name="room"/>{{tr("查实验室")}}</button><button @click="emit('navigate',{view:'automation'})"><UiIcon name="clock"/>{{tr("定时规则")}}</button><button @click="emit('navigate',{view:'messages'})"><UiIcon name="chat"/>{{tr("消息中心")}}</button></nav>
<div class="mobile-home-queues"><section ref="tasksSection" class="mobile-section" :class="{'is-populated':data.tasks.length}"><header class="mobile-section-head"><h3>{{tr("今天要做")}} <small>{{data.tasks.length}}</small></h3><button v-if="data.tasks.length>3" @click="expanded.tasks=!expanded.tasks">{{tr(expanded.tasks?'收起':'更多')}}</button></header><button v-for="t in (expanded.tasks?data.tasks:data.tasks.slice(0,3))" :key="t.id" class="mobile-row" @click="emit('navigate',{view:'task',taskId:t.id})"><b>{{kinds[t.kind]||t.kind}}<span class="mobile-pill">{{states[t.status]||t.status}}</span></b><small>{{t.id}}</small></button><p v-if="!data.tasks.length" class="mobile-empty">{{tr("暂无待办")}}</p></section>
<section ref="plansSection" class="mobile-section" :class="{'is-populated':data.pendingPlans.length}"><header class="mobile-section-head"><h3>{{tr("待本人确认")}} <small>{{data.pendingPlans.length}}</small></h3><button v-if="data.pendingPlans.length>2" @click="expanded.plans=!expanded.plans">{{tr(expanded.plans?'收起':'更多')}}</button></header><button v-for="plan in (expanded.plans?data.pendingPlans:data.pendingPlans.slice(0,2))" :key="plan.id" class="mobile-row" :disabled="!plan.taskId&&!plan.conversationId" @click="emit('navigate',plan.taskId?{view:'task',taskId:plan.taskId}:{view:'conversation',conversationId:plan.conversationId})"><b>{{kinds[plan.kind]||plan.kind}}</b><small>{{plan.id}}</small></button><p v-if="!data.pendingPlans.length" class="mobile-empty">{{tr("暂无待确认方案")}}</p></section>
<section ref="shiftsSection" class="mobile-section" :class="{'is-populated':data.shifts.length+data.handovers.length}"><header class="mobile-section-head"><h3>{{tr("班次与交接")}} <small>{{data.shifts.length+data.handovers.length}}</small></h3><button v-if="data.shifts.length+data.handovers.length>3" @click="expanded.shifts=!expanded.shifts">{{tr(expanded.shifts?'收起':'更多')}}</button></header><button v-for="s in (expanded.shifts?data.shifts:data.shifts.slice(0,2))" :key="s.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:s.roomId,action:'duty'})"><b>{{s.roomId}}<span class="mobile-pill">{{s.periodKey}}</span></b><small>{{s.date}}</small></button><button v-for="h in (expanded.shifts?data.handovers:data.handovers.slice(0,1))" :key="h.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:h.roomId,action:'duty'})">{{tr("待接收 ·")}} {{h.id}}</button><p v-if="!data.shifts.length&&!data.handovers.length" class="mobile-empty">{{tr("暂无班次或交接")}}</p></section>
<section class="mobile-section" :class="{'is-populated':data.issues.length}"><header class="mobile-section-head"><h3>{{tr("我的工单")}} <small>{{data.issues.length}}</small></h3><button v-if="data.issues.length>3" @click="expanded.issues=!expanded.issues">{{tr(expanded.issues?'收起':'更多')}}</button></header><button v-for="i in (expanded.issues?data.issues:data.issues.slice(0,3))" :key="i.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:i.roomId,action:'issues'})"><b>{{i.description}}<span class="mobile-pill">{{states[i.status]||i.status}}</span></b></button><p v-if="!data.issues.length" class="mobile-empty">{{tr("暂无指派工单")}}</p></section>
</div><section v-if="data.risk" class="mobile-section"><header class="mobile-section-head"><h3>{{tr("待核实风险")}} <small>{{data.risk.suspendedRooms.length+data.risk.unassignedIssues.length}}</small></h3><button v-if="data.risk.suspendedRooms.length+data.risk.unassignedIssues.length>3" @click="expanded.risk=!expanded.risk">{{tr(expanded.risk?'收起':'更多')}}</button></header><button v-for="r in (expanded.risk?data.risk.suspendedRooms:data.risk.suspendedRooms.slice(0,2))" :key="r.roomId" class="mobile-row" @click="emit('navigate',{view:'room',roomId:r.roomId})"><b>{{r.roomName}}<span class="mobile-pill is-warning">{{tr("服务停用")}}</span></b></button><button v-for="i in (expanded.risk?data.risk.unassignedIssues:data.risk.unassignedIssues.slice(0,1))" :key="i.id" class="mobile-row" @click="emit('navigate',{view:'room',roomId:i.roomId,action:'issues'})">{{tr("未指派 ·")}} {{i.description}}</button><p v-if="!data.risk.suspendedRooms.length&&!data.risk.unassignedIssues.length" class="mobile-empty">{{tr("暂无上述风险")}}</p></section>
<details class="mobile-source"><summary>{{tr("数据依据")}}</summary>{{tr("主系统授权查询 ·")}} {{data.queriedAt}} · {{data.sourceRevision.slice(0,12)}}</details>
</template></AsyncState></template>
